"""Writes astral_chain/runtime/las/ps5_glyphs.h from the PNGs here: each glyph's alpha, box-filtered from 128x128 to
64x64, for the PlayStation button prompts (las/button_prompts.c, AC_PROMPTS=ps).

The PNGs are "PS5 Button Icons and Controls" by Zacksly (https://zacksly.itch.io), CC BY 3.0 (LICENSE.txt): the
white "Buttons Full Solid" set at 128 px, unmodified here; the header holds them reduced to 64 px alpha.

    python3 third_party/ps5-button-icons/make_header.py
"""
from pathlib import Path
import struct
import zlib

HERE = Path(__file__).resolve().parent
OUT = HERE.parent.parent/'astral_chain'/'runtime'/'las'/'ps5_glyphs.h'
NAMES = ('Cross', 'Circle', 'Triangle', 'Square', 'L1', 'R1', 'L2', 'R2', 'Options', 'Create')
SIZE = 64


def png_alpha(path):
    """The alpha channel of an 8-bit RGBA, non-interlaced PNG, as rows of bytes."""
    data = path.read_bytes()
    assert data[:8] == b'\x89PNG\r\n\x1a\n', path
    pos, idat, w = 8, b'', 0
    while pos < len(data):
        n, kind = struct.unpack('>I4s', data[pos:pos + 8])
        body = data[pos + 8:pos + 8 + n]
        if kind == b'IHDR':
            w, h, depth, color, _, _, interlace = struct.unpack('>IIBBBBB', body)
            assert depth == 8 and color == 6 and not interlace, path
        elif kind == b'IDAT':
            idat += body
        pos += 12 + n
    raw, stride, rows, prev = zlib.decompress(idat), w * 4, [], bytearray(w * 4)
    for y in range(h):
        f, line = raw[y * (stride + 1)], bytearray(raw[y * (stride + 1) + 1:(y + 1) * (stride + 1)])
        for i in range(stride):
            a = line[i - 4] if i >= 4 else 0
            b = prev[i]
            c = prev[i - 4] if i >= 4 else 0
            if f == 1: line[i] = (line[i] + a) & 255
            elif f == 2: line[i] = (line[i] + b) & 255
            elif f == 3: line[i] = (line[i] + (a + b) // 2) & 255
            elif f == 4:
                p = a + b - c
                pa, pb, pc = abs(p - a), abs(p - b), abs(p - c)
                line[i] = (line[i] + (a if pa <= pb and pa <= pc else b if pb <= pc else c)) & 255
        rows.append(bytes(line[3::4]))
        prev = line
    return rows


def main():
    out = ['/* Generated by third_party/ps5-button-icons/make_header.py: do not edit.',
           ' * "PS5 Button Icons and Controls" by Zacksly (https://zacksly.itch.io), CC BY 3.0',
           ' * (third_party/ps5-button-icons/LICENSE.txt); modified: alpha only, reduced to 64x64. */',
           f'#define PS5_GLYPH_SIZE {SIZE}',
           'enum { ' + ', '.join(f'PS5_{n.upper()}' for n in NAMES) + ', PS5_GLYPHS };',
           f'static const unsigned char ps5_glyphs[PS5_GLYPHS][{SIZE} * {SIZE}] = {{']
    for name in NAMES:
        rows = png_alpha(HERE/f'{name}.png')
        k = len(rows) // SIZE
        px = [sum(rows[y * k + j][x * k + i] for j in range(k) for i in range(k)) // (k * k)
              for y in range(SIZE) for x in range(SIZE)]
        out.append(f' {{ /* {name} */')
        for y in range(SIZE):
            out.append('  ' + ','.join(str(v) for v in px[y * SIZE:(y + 1) * SIZE]) + ',')
        out.append(' },')
    out.append('};')
    OUT.write_text('\n'.join(out) + '\n', encoding='ascii')
    print(OUT)


if __name__ == '__main__':
    main()
